<template><view class="shop-page"><BusinessPageHeader :title="heading" :fallback="heading==='会员订单'?'/pages/partners/index':'/pages/profile/index'"/><view class="account-page"><view class="order-tabs"><button v-for="item in filters" :key="item.id" :class="{selected:filter===item.id}" @click="change(item.id)">{{item.label}}</button></view><view class="order-search"><image class="order-search-icon" src="/static/common/icon-search.png" mode="aspectFit"/><input v-model="keyword" confirm-type="search" placeholder="输入关键词搜索" @confirm="load"/><button @click="load">搜索</button></view><view v-if="status==='loading'" class="account-state">正在加载订单…</view><view v-else-if="status==='error'" class="account-state"><text>{{error}}</text><button class="secondary" @click="load">重试</button></view><EmptyState v-else-if="!items.length" text="暂无订单"/><template v-else><view v-for="order in items" :key="order.id" class="order-card" @click="detail(order.id)"><text class="order-status">{{order.status==='PENDING_PAYMENT'?'待支付':(order.statusLabel||'状态待确认')}}</text><view class="order-card-heading"><text>订单编号：{{order.orderNo}}</text></view><view v-for="line in order.items" :key="line.id||line.skuId" class="order-product"><image v-if="line.coverUrl" :src="line.coverUrl" mode="aspectFill"/><view class="order-copy"><view>{{line.title}}</view><text v-if="line.specLabel" class="order-spec">{{line.specLabel}}</text></view><view class="order-price"><text>¥{{money(line.unitAmount)}}</text><text>x{{line.quantity}}</text></view></view><view v-if="order.status!=='CANCELLED'" class="order-amount">{{order.status==='COMPLETED'?'实付款':'待付款'}}：<text>¥{{money(order.payableAmount)}}</text></view></view><button v-if="hasMore" class="secondary" :disabled="loadingMore" @click="more">{{loadingMore?'加载中…':'加载更多'}}</button><text v-if="moreError" class="account-error">{{moreError}}</text></template></view></view></template>
<script setup>
import BusinessPageHeader from '../../components/BusinessPageHeader.vue'
import { ref } from 'vue'
import { onLoad,onShow,onUnload } from '@dcloudio/uni-app'
import { useAuth } from '../../composables/useAuth'
import {getCommerceOrders} from '../../services/commerce'
import {getStoreMember} from '../../services/training'
import { getMyOrders } from '../../services/profile'
import EmptyState from '../../components/EmptyState.vue'
useAuth()
const filters=[{id:'all',label:'全部'},{id:'pending-payment',label:'待付款'},{id:'waiting-shipment',label:'待发货'},{id:'waiting-receipt',label:'待收货'},{id:'completed',label:'已完成'}],filter=ref('all'),keyword=ref(''),status=ref('loading'),items=ref([]),error=ref(''),hasMore=ref(false),loadingMore=ref(false),moreError=ref(''),heading=ref('我的订单')
let epoch=0,cursor=null,searchTerm='',memberId='',contextId=''
function detail(id){uni.navigateTo({url:`/pages/order/detail?id=${encodeURIComponent(id)}${contextId?`&contextId=${encodeURIComponent(contextId)}&memberId=${encodeURIComponent(memberId)}`:''}`})}
async function fetchOrders(cursor){if(!memberId)return getMyOrders(filter.value,cursor,searchTerm);if(contextId){const member=await getStoreMember(contextId,memberId);if(!member.allowedActions.includes('read-orders'))throw new Error('当前身份无权查看订单')}return getCommerceOrders({filter:filter.value,cursor,keyword:searchTerm,memberId,contextId})}
const money=value=>Number.isFinite(value)?(value/100).toFixed(2):'—'
onLoad(options=>{memberId=options.memberId||'';contextId=options.contextId||'';heading.value=memberId?'会员订单':'我的订单';if(filters.some(item=>item.id===options.status))filter.value=options.status})
function change(next){if(next!==filter.value){filter.value=next;load()}}
async function load(){const current=++epoch;status.value='loading';items.value=[];loadingMore.value=false;moreError.value='';searchTerm=keyword.value.trim();try{const result=await fetchOrders(null);if(current===epoch){items.value=result.items;cursor=result.nextCursor;hasMore.value=result.hasMore===true;status.value='ready'}}catch(reason){if(current===epoch){error.value=reason.message;status.value='error'}}}
async function more(){if(loadingMore.value||!hasMore.value)return;const current=epoch;loadingMore.value=true;try{const result=await fetchOrders(cursor);if(current===epoch){items.value=[...new Map([...items.value,...result.items].map(item=>[item.id,item])).values()];cursor=result.nextCursor;hasMore.value=result.hasMore===true}}catch(reason){if(current===epoch)moreError.value=reason.message}finally{if(current===epoch)loadingMore.value=false}}
onShow(load);onUnload(()=>{++epoch})
</script>
<style>@import '../../styles/commerce.css';@import '../../styles/account.css';.order-search-icon{height:40rpx;width:40rpx;flex-shrink:0}</style>
<style scoped>.order-tabs{display:flex;gap:10rpx}.order-tabs button{flex:1;min-width:0;white-space:nowrap;padding:.35em 0 .5em;background:none;margin:0;color:#a7b6cf;font-size:.82em;line-height:1.7;border-radius:0;border-bottom:.18em solid transparent}.order-tabs .selected{color:#fff;border-bottom-color:#00bcff}.order-search{display:flex;align-items:center;gap:16rpx;margin:24rpx 0;background:#444d6d;border-radius:40rpx;padding:8rpx 12rpx 8rpx 24rpx}.order-search input{flex:1;min-width:0;font-size:26rpx;height:56rpx}.order-search button{background:linear-gradient(90deg,#00b7ff,#2a57ff);color:#fff;font-size:24rpx;border-radius:30rpx;margin:0;line-height:2;padding:0 20rpx}.order-card{position:relative;background:#353a59;border-radius:.85em;padding:1em .9em .9em;margin-bottom:.85em}.order-status{position:absolute;top:0;right:0;padding:.15em .7em;border-radius:0 .85em 0 .55em;background:#596381;color:#d7deee;font-size:.78em}.order-card-heading{padding-right:4.2em;font-size:.86em;color:#c5cbe0}.order-product{display:flex;gap:18rpx;margin-top:24rpx;font-size:28rpx;line-height:1.5}.order-product>image{width:4.6em;height:4.6em;border-radius:.4em;flex-shrink:0;background:#2a314c}.order-copy{flex:1;min-width:0;overflow-wrap:anywhere}.order-spec{display:inline-block;margin-top:.35em;padding:.1em .55em;border-radius:1em;background:#4a5170;color:#d5dced;font-size:.75em}.order-price{flex:none;text-align:right;color:#fff}.order-price text{display:block}.order-price text:last-child{color:#a2afc7;font-size:.8em}.order-amount{text-align:right;margin-top:24rpx;color:#a8b7cf;font-size:26rpx}.order-amount>text{color:#ff4c79;font-size:30rpx}.order-search-icon{height:40rpx;width:40rpx;flex-shrink:0}</style>
